 "B.4.1": {
  "code": "B.4.1",
  "topic": "B.4",
  "title": "Thermodynamics",
  "level": "HL",
  "statement": "that the first law of thermodynamics as given by Q = ΔU + W results from the application of conservation of energy to a closed system and relates the internal energy of a system to the transfer of energy as heat and as work"
 },
 "B.4.2": {
  "code": "B.4.2",
  "topic": "B.4",
  "title": "Thermodynamics",
  "level": "HL",
  "statement": "that the work done by or on a closed system as given by W = PΔV when its boundaries are changed can be described in terms of pressure and changes of volume of the system"
 },
 "B.4.3": {
  "code": "B.4.3",
  "topic": "B.4",
  "title": "Thermodynamics",
  "level": "HL",
  "statement": "that the change in internal energy as given by ΔU = 3 2NkBΔT = 3 2nRΔT of a system is related to the change of its temperature"
 },
 "B.4.4": {
  "code": "B.4.4",
  "topic": "B.4",
  "title": "Thermodynamics",
  "level": "HL",
  "statement": "that entropy S is a thermodynamic quantity that relates to the degree of disorder of the particles in a system"
 },
 "B.4.5": {
  "code": "B.4.5",
  "topic": "B.4",
  "title": "Thermodynamics",
  "level": "HL",
  "statement": "that entropy can be determined in terms of macroscopic quantities such as thermal energy and temperature as given by ΔS = ΔQ T and also in terms of the properties of individual particles of the system as given by S = kB ln Ω where kB is the Boltzmann constant and Ω is the number of possible microstates of the system"
 },
 "B.4.6": {
  "code": "B.4.6",
  "topic": "B.4",
  "title": "Thermodynamics",
  "level": "HL",
  "statement": "that the second law of thermodynamics refers to the change in entropy of an isolated system and sets constraints on possible physical processes and on the overall evolution of the system"
 },
 "B.4.7": {
  "code": "B.4.7",
  "topic": "B.4",
  "title": "Thermodynamics",
  "level": "HL",
  "statement": "that processes in real isolated systems are almost always irreversible and consequently the entropy of a real isolated system always increases"
 },
 "B.4.8": {
  "code": "B.4.8",
  "topic": "B.4",
  "title": "Thermodynamics",
  "level": "HL",
  "statement": "that the entropy of a non-isolated system can decrease locally, but this is compensated by an equal or greater increase of the entropy of the surroundings"
 },
 "B.4.9": {
  "code": "B.4.9",
  "topic": "B.4",
  "title": "Thermodynamics",
  "level": "HL",
  "statement": "that isovolumetric, isobaric, isothermal and adiabatic processes are obtained by keeping one variable fixed"
 },
 "B.4.10": {
  "code": "B.4.10",
  "topic": "B.4",
  "title": "Thermodynamics",
  "level": "HL",
  "statement": "that adiabatic processes in monatomic ideal gases can be modelled by the equation as given by PV 5 3 = constant"
 },
 "B.4.11": {
  "code": "B.4.11",
  "topic": "B.4",
  "title": "Thermodynamics",
  "level": "HL",
  "statement": "that cyclic gas processes are used to run heat engines"
 },
 "B.4.12": {
  "code": "B.4.12",
  "topic": "B.4",
  "title": "Thermodynamics",
  "level": "HL",
  "statement": "that a heat engine can respond to different cycles and is characterized by its efficiency as given by η = useful work input energy"
 },
 "B.4.13": {
  "code": "B.4.13",
  "topic": "B.4",
  "title": "Thermodynamics",
  "level": "HL",
  "statement": "that the Carnot cycle sets a limit for the efficiency of a heat engine at the temperatures of its heat reservoirs as given by ηCarnot = 1–Tc Th."
 },
